1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
3	const BLOCK_SIZE = 3;
4	const BLOCK_DISCOUNT_PERCENT = 20;
5	const CURSE_SURCHARGE_PERCENT = 50;
6	const HIGH_ENCHANTMENT_THRESHOLD = 5;
7	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
8	const LOYALTY_YEARS_THRESHOLD = 2;
9	const LOYALTY_DISCOUNT_PERCENT = 20;
10	const FOLLOW_UP_DISCOUNT_PERCENT = 15;
11	const DEDUCTIBLE = 100;
12	const CAP_MULTIPLE = 2;
13	// Distinct from HIGH_ENCHANTMENT_THRESHOLD (5): a sword can be enchanted enough
14	// to cost more to insure without being enchanted enough to pay out less.
15	const CLAIM_HIGH_ENCHANTMENT_THRESHOLD = 8;
16	const HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT = 50;
17	
18	const BASE_PREMIUMS = {
19	  sword: 100,
20	  amulet: 60,
21	  staff: 80,
22	  potion: 40,
23	  rune: 25,
24	  moonstone: 25,
25	} as const;
26	
27	// What an item is insured FOR, as opposed to what insuring it costs. The cap on
28	// claims is derived from these, so premium discounts never move it.
29	const INSURANCE_VALUES = {
30	  sword: 1000,
31	  amulet: 600,
32	  staff: 800,
33	  potion: 400,
34	  rune: 250,
35	  moonstone: 250,
36	} as const;
37	
38	// The six priced types are the domain, so they are derived from the premium
39	// table rather than restated: a type nobody prices cannot be insured. The
40	// unknown-type case (broomstick) is still a runtime error the tests will drive.
41	type ItemType = keyof typeof BASE_PREMIUMS;
42	
43	// Components (as opposed to main items) are the only things the block rule
44	// applies to, so the distinction has to be data, not a price coincidence.
45	// Typed as a set of ItemType so a component can never name an unpriced type.
46	const COMPONENT_TYPES = new Set<ItemType>(["rune", "moonstone"]);
47	
48	const PERCENT_WHOLE = 100;
49	
50	// Divides rather than multiplying by a rate: `amount * 1.1` introduces
51	// floating-point error that shifts the spec's round-up in MHPCO's favour.
52	const percentOf = (percent: number, amount: number): number =>
53	  (amount * percent) / PERCENT_WHOLE;
54	
55	// MHPCO rounds every money amount in its own favour: premiums (customer pays)
56	// round up, payouts (MHPCO pays) round down.
57	const roundPremiumInMHPCOsFavour = Math.ceil;
58	
59	export type QuoteResult = { premium: number };
60	
61	export type ClaimResult = { payout: number; remainingCap: number };
62	
63	export type ScenarioResult = QuoteResult | ClaimResult;
64	
65	// `material` is still unread — the dragon-material claim clause will reach for
66	// it. All three are optional so a bare `{ type: "rune" }` typechecks: a rune has
67	// no enchantment to speak of, rather than an enchantment of zero.
68	type Item = {
69	  type: ItemType;
70	  material?: string;
71	  enchantment?: number;
72	  cursed?: boolean;
73	};
74	
75	type Damage = { itemType: string; amount: number };
76	
77	type Incident = { cause: string; damages: Damage[] };
78	
79	type QuoteStep = { op: "quote"; items: Item[] };
80	
81	type ClaimStep = { op: "claim"; policy: number; incident: Incident };
82	
83	type Step = QuoteStep | ClaimStep;
84	
85	const isQuote = (step: Step): step is QuoteStep => step.op === "quote";
86	
87	type Customer = { yearsWithMHPCO: number };
88	
89	type Scenario = {
90	  customer: Customer;
91	  steps: Step[];
92	};
93	
94	const sum = (amounts: number[]): number =>
95	  amounts.reduce((total, amount) => total + amount, 0);
96	
97	const basePremiumForItem = (item: Item): number => BASE_PREMIUMS[item.type];
98	
99	const sumBasePremiums = (items: Item[]): number => sum(items.map(basePremiumForItem));
100	
101	// Groups of items that are "alike" — same type. The type is kept alongside the
102	// items because the block rule asks about it; recovering it from items[0] would
103	// make every reader re-derive that a group is non-empty and homogeneous.
104	type AlikeItems = { type: ItemType; items: Item[] };
105	
106	const groupByType = (items: Item[]): AlikeItems[] => {
107	  const groups = new Map<ItemType, Item[]>();
108	  for (const item of items) {
109	    const group = groups.get(item.type) ?? [];
110	    group.push(item);
111	    groups.set(item.type, group);
112	  }
113	  return [...groups].map(([type, groupedItems]) => ({ type, items: groupedItems }));
114	};
115	
116	// A block is a discount on the components' combined base premium, not a flat
117	// price: 3 runes are 75 G less 20 % = 60 G. Derived rather than hardcoded so the
118	// 20 % stays visible as the rule it is.
119	const blockBasePremium = (items: Item[]): number => {
120	  const undiscounted = sumBasePremiums(items);
121	  return undiscounted - percentOf(BLOCK_DISCOUNT_PERCENT, undiscounted);
122	};
123	
124	// Exactly BLOCK_SIZE, not "at least": 4 or 7 runes form no block, so a bigger
125	// pile is never cheaper than the block it contains. Components only — three
126	// swords are three separate insurances, not a discounted building block.
127	const formsABlock = ({ type, items }: AlikeItems): boolean =>
128	  items.length === BLOCK_SIZE && COMPONENT_TYPES.has(type);
129	
130	const basePremiumForGroup = (alikeItems: AlikeItems): number =>
131	  formsABlock(alikeItems)
132	    ? blockBasePremium(alikeItems.items)
133	    : sumBasePremiums(alikeItems.items);
134	
135	// Priced per group of alike items rather than over the whole list, so 3 runes
136	// and 3 moonstones each form their own block.
137	const policyBasePremiumFor = (items: Item[]): number =>
138	  sum(groupByType(items).map(basePremiumForGroup));
139	
140	const percentOfWhen = (applies: boolean, percent: number, amount: number): number =>
141	  applies ? percentOf(percent, amount) : 0;
142	
143	// Each item-specific surcharge is a percentage of the affected item's OWN base
144	// premium, so every rule reads as "this much, when this holds". The terms are
145	// summed rather than chosen between: an item can trigger several at once.
146	//
147	// Deliberately two explicit terms rather than a table of rules. The shared
148	// shape is only the arithmetic tail; the conditions differ in kind (a flag vs.
149	// a threshold over an optional number), and nothing in the remaining spec adds
150	// a third item-specific surcharge to generalise over.
151	const surchargeFor = (item: Item): number => {
152	  const base = basePremiumForItem(item);
153	  return (
154	    percentOfWhen(item.cursed === true, CURSE_SURCHARGE_PERCENT, base) +
155	    percentOfWhen(
156	      (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
157	      HIGH_ENCHANTMENT_SURCHARGE_PERCENT,
158	      base,
159	    )
160	  );
161	};
162	
163	// Charged alongside the policy base premium — never folded into it, or the
164	// policy-wide modifiers would compound on top of them.
165	const itemSurchargesFor = (items: Item[]): number => sum(items.map(surchargeFor));
166	
167	// Unlike the item-specific surcharges, these are percentages of the WHOLE
168	// policy's base premium. Each is returned already signed — a surcharge is
169	// positive, a discount negative — so the rule and its direction stay on one
170	// line instead of the sign living in a `+`/`-` further down the sum.
171	const policyModifiersFor = (
172	  policyBasePremium: number,
173	  customer: Customer,
174	  isFollowUpContract: boolean,
175	): number[] => [
176	  // Applies to every quote, follow-ups included: the spec treats each item in a
177	  // quote as newly insured, regardless of how long the customer has been around.
178	  percentOf(FIRST_INSURANCE_SURCHARGE_PERCENT, policyBasePremium),
179	  -percentOfWhen(
180	    customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD,
181	    LOYALTY_DISCOUNT_PERCENT,
182	    policyBasePremium,
183	  ),
184	  -percentOfWhen(isFollowUpContract, FOLLOW_UP_DISCOUNT_PERCENT, policyBasePremium),
185	];
186	
187	// The order of the terms is the order of the spec's rules: what the items are
188	// worth, what they individually cost extra, what the policy as a whole is
189	// adjusted by, and MHPCO's fee on top.
190	const quoteFor = (
191	  items: Item[],
192	  customer: Customer,
193	  isFollowUpContract: boolean,
194	): QuoteResult => {
195	  const policyBasePremium = policyBasePremiumFor(items);
196	  const premium = roundPremiumInMHPCOsFavour(
197	    policyBasePremium +
198	      itemSurchargesFor(items) +
199	      sum(policyModifiersFor(policyBasePremium, customer, isFollowUpContract)) +
200	      PROCESSING_FEE,
201	  );
202	  return { premium };
203	};
204	
205	// A follow-up contract is any quote after the customer's first, so what counts
206	// is how many QUOTES precede this step — not how many steps do. Claim steps sit
207	// in the same list and must not push a later quote into follow-up territory.
208	const isFollowUpContract = (precedingSteps: Step[]): boolean =>
209	  precedingSteps.some(isQuote);
210	
211	const insuranceSumFor = (items: Item[]): number =>
212	  sum(items.map((item) => INSURANCE_VALUES[item.type]));
213	
214	// MHPCO pays, so payouts round down.
215	const roundPayoutInMHPCOsFavour = Math.floor;
216	
217	// Each damage entry carries its own deductible: one dragon attack damaging two
218	// items is two damages, and MHPCO withholds 100 G from each. The reimbursement
219	// clauses apply to the damage amount FIRST, so the deductible bites last.
220	const payoutForDamage = (damage: Damage, damagedItem: Item): number => {
221	  const reimbursable =
222	    (damagedItem.enchantment ?? 0) >= CLAIM_HIGH_ENCHANTMENT_THRESHOLD
223	      ? percentOf(HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT, damage.amount)
224	      : damage.amount;
225	  return reimbursable - DEDUCTIBLE;
226	};
227	
228	// Which insured item a damage entry refers to, since the reimbursement clauses
229	// depend on that item's enchantment and material. Nothing validates that the
230	// policy actually covers the damaged type yet; the error-case tests will turn
231	// this throw into a reported error.
232	const damagedItemFor = (damage: Damage, insuredItems: Item[]): Item => {
233	  const item = insuredItems.find((insured) => insured.type === damage.itemType);
234	  if (item === undefined) {
235	    throw new Error(`Claim damages a ${damage.itemType}, which this policy does not cover`);
236	  }
237	  return item;
238	};
239	
240	// The cap is a property of the POLICY, not of the claim: twice what the policy's
241	// items are insured for. Kept separate from the payout so the cross-claim
242	// accumulation the spec still demands has an obvious place to attach.
243	const capFor = (policy: QuoteStep): number =>
244	  insuranceSumFor(policy.items) * CAP_MULTIPLE;
245	
246	const claimFor = (claim: ClaimStep, policy: QuoteStep): ClaimResult => {
247	  const payout = roundPayoutInMHPCOsFavour(
248	    sum(
249	      claim.incident.damages.map((damage) =>
250	        payoutForDamage(damage, damagedItemFor(damage, policy.items)),
251	      ),
252	    ),
253	  );
254	  return { payout, remainingCap: capFor(policy) - payout };
255	};
256	
257	// `claim.policy` indexes the scenario's steps, and the referenced step must be a
258	// quote — a claim against a claim is meaningless. Nothing validates the scenario
259	// yet, so this states the assumption instead of casting past it; the
260	// error-case tests will turn the throw into a reported error.
261	const policyReferencedBy = (claim: ClaimStep, steps: Step[]): QuoteStep => {
262	  const step = steps[claim.policy];
263	  if (step === undefined || !isQuote(step)) {
264	    throw new Error(`Claim references step ${claim.policy}, which is not a quote`);
265	  }
266	  return step;
267	};
268	
269	export const runScenario = (scenario: Scenario): { results: ScenarioResult[] } => {
270	  const results = scenario.steps.map((step, stepIndex) =>
271	    isQuote(step)
272	      ? quoteFor(
273	          step.items,
274	          scenario.customer,
275	          isFollowUpContract(scenario.steps.slice(0, stepIndex)),
276	        )
277	      : claimFor(step, policyReferencedBy(step, scenario.steps)),
278	  );
279	  return { results };
280	};
